def seed_existing_publications(apps, schema_editor):
    Premises = apps.get_model("leasefit", "Premises")
    Publication = apps.get_model("leasefit", "ListingPublication")
    Version = apps.get_model("leasefit", "ListingPublicationVersion")
    names = {
        "Авито": "avito", "Циан": "cian", "Домклик": "domclick",
        "Яндекс Недвижимость": "yandex", "FarPost": "farpost",
        "Move.ru": "move", "sob.ru": "sob", "Юла": "youla",
    }
    alias = schema_editor.connection.alias
    for p in Premises.objects.using(alias).select_related("listing").order_by("pk").iterator():
        media = getattr(p, "listing", None)
        if media:
            source, source_id = media.source, media.source_id
        else:
            prefix, _, origin = p.commercial_source.partition(" / ")
            name, _, source_id = origin.partition(" / ")
            source = names.get(name) if prefix == "Metrapi" else None
        if source not in names.values() or not re.fullmatch(r"[A-Za-z0-9_-]{1,80}", source_id):
            continue
        snapshot = {
            "state": "legacy", "url": media.url if media else p.listing_url,
            "description": media.description if media else "",
            "photos": media.photos if media else [],
        }
        publication, created = Publication.objects.using(alias).get_or_create(
            agency_id=p.agency_id, source=source, source_id=source_id,
            defaults={"premises_id": p.pk, "version": 1, "snapshot": snapshot},
        )
        if created:
            Version.objects.using(alias).create(
                publication=publication, number=1, snapshot=snapshot,
            )


